from collections import deque
from copy import deepcopy

class Orders:
    def __init__(self, data):
        self.orders=deepcopy(data['orders'])
        self.sessions=deepcopy(data['sessions'])
        self.origin=data['trusted_origin']
        self.queue=deque()
        self.events=[]

    def request(self, route, request, revision):
        if route not in ('action','callback') or revision not in ('old','fixed'):
            raise ValueError('unknown route/revision')
        session=self.sessions.get(request.get('session'))
        if session is None:return 'unauthenticated'
        if request.get('method')!='POST':return 'method-denied'
        protected=route=='action' or revision=='fixed'
        if protected:
            if request.get('origin')!=self.origin:return 'origin-denied'
            if request.get('csrf')!=session['csrf']:return 'token-denied'
        order=self.orders.get(request.get('order'))
        if order is None:return 'not-found'
        if order['owner']!=session['actor']:return 'owner-denied'
        job={'actor':session['actor'],'order':request['order'],'action':'cancel'}
        if route=='callback':
            self.queue.append(job)
            return 'queued'
        return self.worker(job)

    def worker(self, job):
        order=self.orders[job['order']]
        if order['owner']!=job['actor']:return 'owner-denied'
        before=order['state']
        if before!='open':return 'no-change'
        order['state']='cancelled'
        self.events.append({'order':job['order'],'before':before,'after':order['state']})
        return 'changed'

    def drain(self):
        outcomes=[]
        while self.queue:outcomes.append(self.worker(self.queue.popleft()))
        return outcomes
